package io.nebulaflow.runner;
import io.nebulaflow.engine.DagPlanner; import io.nebulaflow.rag.RagService; import java.util.*; import org.springframework.stereotype.Component;
@Component public class RagQueryTaskRunner implements TaskRunner { private final RagService service; public RagQueryTaskRunner(RagService service){this.service=service;} public String type(){return "RAG_QUERY";}
 public Object run(DagPlanner.Node node,Map<String,Object> context,TaskContext task){Map<String,Object> c=node.config();String collection=str(c.getOrDefault("collection","default"),"collection");String query=str(c.getOrDefault("query",task.input().get("query")),"query");int topK=num(c.getOrDefault("topK",5),"topK");double min=dec(c.getOrDefault("minScore",0.0),"minScore");var r=service.query(task.tenantId(),collection,query,topK,min);return Map.of("collection",r.collection(),"query",r.query(),"matches",r.matches(),"context",r.context());} private static String str(Object x,String n){if(x==null||String.valueOf(x).isBlank())throw new IllegalArgumentException(n+" is required");return String.valueOf(x);} private static int num(Object x,String n){if(!(x instanceof Number v))throw new IllegalArgumentException(n+" must be numeric");return v.intValue();} private static double dec(Object x,String n){if(!(x instanceof Number v))throw new IllegalArgumentException(n+" must be numeric");return v.doubleValue();} }